package gateway_test

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"reflect"
	"testing"

	"projectmesh.io/mesh-cli/internal/gateway"
)

// jobFixture is a runsheet contract fixture of the job API
// (specs/contracts, generated by runsheet's TestContracts).
type jobFixture struct {
	Field  string          `json:"field"`
	Input  json.RawMessage `json:"input"`
	Args   json.RawMessage `json:"args"`
	Result json.RawMessage `json:"result"`
	Sample json.RawMessage `json:"sample"`
}

func readJobFixture(t *testing.T, name string) jobFixture {
	t.Helper()
	raw, err := os.ReadFile("../../specs/contracts/" + name + ".json")
	if err != nil {
		t.Fatal(err)
	}
	var fx jobFixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
	return fx
}

// fixtureServer answers field with answer and keeps the request's
// variables.
func fixtureServer(t *testing.T, field string, answer json.RawMessage) (*gateway.Client, *map[string]any) {
	t.Helper()
	var sent map[string]any
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Variables map[string]any `json:"variables"`
		}
		_ = json.NewDecoder(r.Body).Decode(&req)
		sent = req.Variables
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"data": map[string]any{field: answer}})
	}))
	t.Cleanup(srv.Close)
	return gateway.New(srv.URL, "rs_test"), &sent
}

// claimJob, called with the fixture's own input, sends it as the
// fixture's input, and its answer decodes into the brief, field for field.
func TestClaimJobSendsAndReadsTheContract(t *testing.T) {
	fx := readJobFixture(t, "claimJob")
	var in struct {
		Input map[string]any `json:"input"`
	}
	if err := json.Unmarshal(fx.Input, &in); err != nil {
		t.Fatal(err)
	}
	gw, sent := fixtureServer(t, "claimJob", fx.Result)
	subject, _ := in.Input["subject"].(map[string]any)
	str := func(m map[string]any, k string) string { s, _ := m[k].(string); return s }
	brief, err := gw.ClaimJob(context.Background(), gateway.ClaimJobInput{NodeID: str(in.Input, "nodeId"), Kind: str(in.Input, "kind"),
		Subject: gateway.JobSubject{Type: str(subject, "type"), ID: str(subject, "id")}, Harness: str(in.Input, "harness")})
	if err != nil {
		t.Fatal(err)
	}
	if got := (*sent)["in"]; !reflect.DeepEqual(got, in.Input) {
		t.Fatalf("input = %v, want the contract's %v", got, in.Input)
	}
	var result struct {
		Job map[string]any `json:"job"`
	}
	_ = json.Unmarshal(fx.Result, &result)
	if brief.Kind != result.Job["kind"] || brief.Finish != result.Job["finish"] || brief.Claim != result.Job["claim"] ||
		brief.Harness != result.Job["harness"] || len(brief.Pods) != len(result.Job["pods"].([]any)) || brief.Code.Form == "" {
		t.Fatalf("brief %+v, contract %v", brief, result.Job)
	}
	// the kind's guidance text and its finish_schema ride the brief
	// (runsheet ADR 067 decisions 7 and 10); the fixture names both
	// fields, so a brief without them is a contract the node no longer
	// reads
	guidance, hasGuidance := result.Job["guidance"].(string)
	schema, hasSchema := result.Job["finishSchema"].(string)
	if !hasGuidance || !hasSchema || brief.Guidance != guidance || brief.FinishSchema != schema {
		t.Fatalf("brief guidance %q schema %q, contract guidance %v schema %v", brief.Guidance, brief.FinishSchema, result.Job["guidance"], result.Job["finishSchema"])
	}
}

// The job-kind catalogue's answer decodes, kind by kind: each kind's
// slug, finish, guidance text and finish_schema (ADR 067).
func TestJobKindsReadsTheContract(t *testing.T) {
	fx := readJobFixture(t, "jobKinds")
	var args struct {
		Method, Path string
	}
	_ = json.Unmarshal(fx.Args, &args)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != args.Method || r.URL.Path != args.Path {
			http.Error(w, r.Method+" "+r.URL.Path, http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write(fx.Sample)
	}))
	t.Cleanup(srv.Close)
	kinds, err := gateway.New(srv.URL, "rs_test").JobKinds(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	var sample struct {
		Kinds []map[string]any `json:"kinds"`
	}
	_ = json.Unmarshal(fx.Sample, &sample)
	if len(kinds) != len(sample.Kinds) {
		t.Fatalf("%d kinds, contract %d", len(kinds), len(sample.Kinds))
	}
	for _, row := range sample.Kinds {
		k, ok := kinds[row["slug"].(string)]
		schema, hasSchema := row["finishSchema"].(string)
		if !ok || !hasSchema || k.Finish != row["finish"] || k.Guidance != row["guidance"] || k.FinishSchema != schema || len(k.Harness) != len(row["harness"].([]any)) {
			t.Fatalf("kind %+v, contract %v", k, row)
		}
	}
}

// jobAccess's answer decodes: its kind, subject, access and what was not
// served, with why.
func TestJobAccessReadsTheContract(t *testing.T) {
	fx := readJobFixture(t, "jobAccess")
	gw, _ := fixtureServer(t, "jobAccess", fx.Sample)
	var sample map[string]any
	_ = json.Unmarshal(fx.Sample, &sample)
	subject, _ := sample["subject"].(map[string]any)
	acc, err := gw.JobAccess(context.Background(), sample["kind"].(string), gateway.JobSubject{Type: subject["type"].(string), ID: subject["id"].(string)}, "")
	if err != nil {
		t.Fatal(err)
	}
	if acc.Kind != sample["kind"] || len(acc.Access) != len(sample["access"].([]any)) {
		t.Fatalf("access %+v, contract %v", acc, sample)
	}
	if ns, _ := sample["notServed"].([]any); len(ns) > 0 {
		first := ns[0].(map[string]any)
		if acc.Missing(first["access"].(string)) != first["reason"] {
			t.Fatalf("notServed %+v, contract %v", acc.NotServed, ns)
		}
	}
}

// threadMessages' answer decodes into the thread and its messages.
func TestThreadMessagesReadsTheContract(t *testing.T) {
	fx := readJobFixture(t, "threadMessages")
	gw, _ := fixtureServer(t, "threadMessages", fx.Sample)
	var sample map[string]any
	_ = json.Unmarshal(fx.Sample, &sample)
	th, err := gw.ThreadMessages(context.Background(), sample["threadId"].(string))
	if err != nil {
		t.Fatal(err)
	}
	msgs := sample["messages"].([]any)
	first := msgs[0].(map[string]any)
	if th.Role != sample["role"] || th.ProjectID != sample["projectId"] || !th.Waiting() || len(th.Messages) != len(msgs) ||
		th.Messages[0].Body != first["body"] || th.Messages[0].From != first["from"] {
		t.Fatalf("thread %+v, contract %v", th, sample)
	}
}
